package app.yoru.anime;

import android.app.*;
import android.os.Bundle;
import android.content.Intent;
import android.text.TextUtils;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

public final class DetailActivity extends Activity {
 Anime anime;List<Episode> videos=new ArrayList<>();String voice="",player="",number="1";Episode selected;Library library;
 TextView status,description,animeTitle,metadata,score;Button voiceButton,playerButton,seriesButton,watch,favorite,retry,expand;ImageView poster;
 boolean expanded;long lastReadVideoId;int generation;
 @Override public void onCreate(Bundle saved){
  super.onCreate(saved);library=new Library(this);try{anime=new Anime(new JSONObject(getIntent().getStringExtra("anime")));}catch(Exception exception){finish();return;}
  if(saved!=null){voice=saved.getString("voice","");player=saved.getString("player","");number=saved.getString("number","1");expanded=saved.getBoolean("expanded");lastReadVideoId=saved.getLong("last_read_video");}
  else{JSONObject last=library.last(anime.id);lastReadVideoId=last==null?0:last.optLong("video_id");}
  LinearLayout window=Ui.root(this);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);LinearLayout content=Ui.column(this);scroll.addView(content);window.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  LinearLayout toolbar=Ui.row(this);toolbar.setPadding(Ui.dp(this,8),Ui.dp(this,4),Ui.dp(this,8),Ui.dp(this,4));Button back=Ui.iconButton(this,"back","Назад в каталог");back.setOnClickListener(v->finish());toolbar.addView(back);TextView heading=Ui.title(this,"Об аниме",16);toolbar.addView(heading,new LinearLayout.LayoutParams(0,-2,1));favorite=Ui.iconButton(this,"heart","Добавить в избранное");favorite.setOnClickListener(v->{library.toggle(anime);updateFavorite();});toolbar.addView(favorite);content.addView(toolbar);
  LinearLayout hero=Ui.row(this);hero.setGravity(Gravity.TOP);hero.setPadding(Ui.dp(this,20),Ui.dp(this,16),Ui.dp(this,20),Ui.dp(this,24));poster=new ImageView(this);Ui.round(poster,14);poster.setContentDescription("Постер: "+anime.title);hero.addView(poster,new LinearLayout.LayoutParams(Ui.dp(this,104),Ui.dp(this,150)));
  LinearLayout about=Ui.column(this);LinearLayout.LayoutParams infoParams=new LinearLayout.LayoutParams(0,-2,1);infoParams.leftMargin=Ui.dp(this,18);hero.addView(about,infoParams);animeTitle=Ui.title(this,anime.title,21);about.addView(animeTitle);score=Ui.text(this,anime.score(),13,Ui.ACCENT);Ui.add(about,score,12);metadata=Ui.text(this,anime.meta(),13,Ui.MUTED);Ui.add(about,metadata,9);content.addView(hero);
  LinearLayout watchCard=Ui.padded(this,16);watchCard.setBackground(Ui.shape(this,Ui.PANEL,18));watchCard.addView(Ui.title(this,"Как будем смотреть?",18));status=Ui.text(this,"Загружаем серии…",13,Ui.MUTED);Ui.add(watchCard,status,8);
  voiceButton=Ui.field(this,"Озвучка");playerButton=Ui.field(this,"Источник");seriesButton=Ui.field(this,"Серия");voiceButton.setEnabled(false);playerButton.setEnabled(false);seriesButton.setEnabled(false);Ui.add(watchCard,voiceButton,16);
  LinearLayout choices=Ui.row(this);choices.addView(playerButton,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(0,-2,1);sp.leftMargin=Ui.dp(this,8);choices.addView(seriesButton,sp);Ui.add(watchCard,choices,8);
  watch=Ui.button(this,"Смотреть",true);watch.setEnabled(false);Ui.icon(watch,"play",0xFF201A30);watch.setCompoundDrawablePadding(Ui.dp(this,8));Ui.add(watchCard,watch,16);watch.setOnClickListener(v->{if(selected!=null)startActivity(new Intent(this,StreamResolver.supports(selected.url)?PlayerActivity.class:WebPlayerActivity.class).putExtra("anime_id",anime.id).putExtra("video_id",selected.id));});
  retry=Ui.textButton(this,"Повторить загрузку");retry.setVisibility(View.GONE);Ui.add(watchCard,retry,8);retry.setOnClickListener(v->load());LinearLayout.LayoutParams cardParams=new LinearLayout.LayoutParams(-1,-2);cardParams.setMargins(Ui.dp(this,20),0,Ui.dp(this,20),Ui.dp(this,24));content.addView(watchCard,cardParams);
  LinearLayout synopsis=Ui.padded(this,20);synopsis.setPadding(Ui.dp(this,20),0,Ui.dp(this,20),Ui.dp(this,24));synopsis.addView(Ui.title(this,"О чём эта история",18));description=Ui.text(this,"",15,Ui.MUTED);description.setEllipsize(TextUtils.TruncateAt.END);Ui.add(synopsis,description,12);expand=Ui.textButton(this,"Читать дальше");expand.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);expand.setPadding(0,0,Ui.dp(this,12),0);expand.setOnClickListener(v->{expanded=!expanded;updateDescription();});Ui.add(synopsis,expand,4);Button site=Ui.textButton(this,"Открыть на YummyAnime");Ui.icon(site,"external",Ui.ACCENT);site.setCompoundDrawablePadding(Ui.dp(this,8));Ui.add(synopsis,site,16);site.setOnClickListener(v->Ui.site(this,anime));content.addView(synopsis);
  voiceButton.setOnClickListener(v->Ui.choose(this,"Озвучка",Sources.voices(videos),voice,choice->{voice=choice;List<String>providers=Sources.players(videos,voice);if(!providers.contains(player))player=providers.isEmpty()?"":providers.get(0);update();}));
  playerButton.setOnClickListener(v->Ui.choose(this,"Источник видео",Sources.players(videos,voice),player,choice->{player=choice;update();}));seriesButton.setOnClickListener(v->{List<Episode>episodes=Sources.episodes(videos,voice,player);List<String>labels=new ArrayList<>();for(Episode episode:episodes)labels.add(episode.label());Ui.choose(this,"Серия",labels,"Серия "+number,label->{number=episodes.get(labels.indexOf(label)).number;update();});});
  updateMetadata();load();
 }
 void updateMetadata(){animeTitle.setText(anime.title);metadata.setText(anime.meta());score.setText(anime.score());Ui.poster(this,poster,anime.poster);updateDescription();updateFavorite();}
 void updateDescription(){description.setText(anime.description.isEmpty()?"Описание пока не добавлено.":anime.description);description.setMaxLines(expanded?Integer.MAX_VALUE:4);expand.setText(expanded?"Свернуть":"Читать дальше");description.post(()->{android.text.Layout layout=description.getLayout();boolean clipped=layout!=null&&(layout.getLineCount()>4||(layout.getLineCount()>0&&layout.getEllipsisCount(Math.min(3,layout.getLineCount()-1))>0));expand.setVisibility((expanded&&!anime.description.isEmpty())||clipped?View.VISIBLE:View.GONE);});}
 void updateFavorite(){boolean saved=library.favorite(anime.id);Ui.icon(favorite,saved?"heart-fill":"heart",saved?Ui.ACCENT:Ui.TEXT);favorite.setContentDescription(saved?"Убрать из избранного":"Добавить в избранное");favorite.setSelected(saved);}
 @Override protected void onSaveInstanceState(Bundle saved){saved.putString("voice",voice);saved.putString("player",player);saved.putString("number",number);saved.putBoolean("expanded",expanded);saved.putLong("last_read_video",lastReadVideoId);super.onSaveInstanceState(saved);}
 @Override protected void onResume(){super.onResume();if(library==null||anime==null||videos.isEmpty())return;updateFavorite();JSONObject last=library.last(anime.id);if(last!=null&&last.optLong("video_id")!=lastReadVideoId){lastReadVideoId=last.optLong("video_id");String newVoice=last.optString("voice"),newPlayer=last.optString("player"),newNumber=last.optString("number");if(Sources.match(videos,newVoice,newPlayer,newNumber)!=null){voice=newVoice;player=newPlayer;number=newNumber;update();}}}
 void load(){
  int request=++generation;status.setText("Загружаем серии и озвучки…");retry.setVisibility(View.GONE);voiceButton.setEnabled(false);playerButton.setEnabled(false);seriesButton.setEnabled(false);watch.setEnabled(false);
  Api.IO.execute(()->{try{
   JSONObject raw=Api.get("anime/"+anime.id+"?need_videos=true").getJSONObject("response");Api.save(this,raw);List<Episode>result=Api.videos(raw);Anime fresh=new Anime(raw);
   runOnUiThread(()->{if(isDestroyed()||request!=generation)return;anime=fresh;videos=result;updateMetadata();if(videos.isEmpty()){status.setText("Пока нет доступных серий. Можно открыть аниме на сайте.");return;}JSONObject last=library.last(anime.id);if(voice.isEmpty()&&last!=null){voice=last.optString("voice");player=last.optString("player");number=last.optString("number","1");lastReadVideoId=last.optLong("video_id");}List<String>voices=Sources.voices(videos);if(!voices.contains(voice))voice=voices.get(0);List<String>providers=Sources.players(videos,voice);if(!providers.contains(player))player=providers.get(0);List<Episode>episodes=Sources.episodes(videos,voice,player);if(last==null&&Sources.match(videos,voice,player,number)==null&&!episodes.isEmpty())number=episodes.get(0).number;voiceButton.setEnabled(true);playerButton.setEnabled(true);seriesButton.setEnabled(true);update();});
  }catch(Exception exception){runOnUiThread(()->{if(isDestroyed()||request!=generation)return;status.setText(exception instanceof java.io.IOException?exception.getMessage():"Не получилось загрузить серии. Попробуй ещё раз.");retry.setVisibility(View.VISIBLE);});}});
 }
 void update(){selected=Sources.match(videos,voice,player,number);Ui.fieldValue(voiceButton,"Озвучка",Ui.voice(voice));Ui.fieldValue(playerButton,"Источник",Ui.provider(player));Ui.fieldValue(seriesButton,"Серия",selected==null?"Выбрать":number);watch.setEnabled(selected!=null);boolean nativeVideo=selected!=null&&StreamResolver.supports(selected.url);watch.setText(selected==null||nativeVideo?"Смотреть · серия "+number:"Открыть плеер сайта");status.setText(selected==null?"Этой серии здесь нет. Выбери другой номер.":nativeVideo?(library.position(selected.id)>0?"Продолжим с "+PlaybackProgress.time(library.position(selected.id)):"Всё готово к просмотру"):"У этого источника может быть реклама. Для своего плеера выбери Kodik.");}
}
